#pragma once

// 16-bit binary angles (ARCHITECTURE §4.3): 65536 units = one full turn, so wrapping is free.
// 0 = +X, 16384 = +Y (counter-clockwise). sin/cos/atan2 use integer lookup tables with linear
// interpolation (sim/math/trig_tables.inc, generated by tools/gen_trig_tables.py).

#include <cstdint>

#include "math/fixed.hpp"

namespace corps {

struct Angle {
    static constexpr std::uint32_t kFullTurn = 65536;
    static constexpr std::uint16_t kQuarter = 16384;
    static constexpr std::uint16_t kHalf = 32768;

    std::uint16_t units = 0;

    static constexpr Angle fromUnits(std::uint32_t u) noexcept { return Angle{static_cast<std::uint16_t>(u)}; }
    // Degrees → angle, rounded to the nearest unit, any value (wraps).
    static Angle fromDegrees(Fixed degrees) noexcept;
    Fixed toDegrees() const noexcept;  // [0, 360)
    // Signed difference in (-32768, 32767] units: the shortest turn from `from` to `to`.
    static constexpr std::int32_t delta(Angle from, Angle to) noexcept {
        return static_cast<std::int16_t>(static_cast<std::uint16_t>(to.units - from.units));
    }

    friend constexpr Angle operator+(Angle a, Angle b) noexcept { return fromUnits(a.units + b.units); }
    friend constexpr Angle operator-(Angle a, Angle b) noexcept { return fromUnits(a.units - b.units + kFullTurn); }
    friend constexpr Angle operator-(Angle a) noexcept { return fromUnits(kFullTurn - a.units); }
    friend constexpr bool operator==(Angle a, Angle b) noexcept { return a.units == b.units; }
    friend constexpr bool operator!=(Angle a, Angle b) noexcept { return a.units != b.units; }
};

Fixed sin(Angle a) noexcept;
Fixed cos(Angle a) noexcept;
// Angle of the vector (x, y). atan2(0, 0) = 0. Exact symmetric octant handling.
Angle atan2(Fixed y, Fixed x) noexcept;

}  // namespace corps
